function cdFaceAxes(G){if(G.A)return G.A;const ix=G.f[0],P=ix.map(i=>G.v[i]),c=[0,1,2].map(a=>P.reduce((t,p)=>t+p[a],0)/P.length),n=G.n[0],top=G.v[ix[0]];let u=[0,1,2].map(a=>top[a]-c[a]);const d=u[0]*n[0]+u[1]*n[1]+u[2]*n[2];u=u.map((x,a)=>x-d*n[a]);const l=Math.hypot(...u)||1;u=u.map(x=>x/l);const r=[u[1]*n[2]-u[2]*n[1],u[2]*n[0]-u[0]*n[2],u[0]*n[1]-u[1]*n[0]];return G.A=[r,u,n,c]}
