const cornerDie=(kind,pal=kind,off=0,sym='')=>{const id='cd'+kind+(cdSeq++),c=cdPal(pal,kind),face=!!sym;return `<svg class="cd-svg" data-die="${kind}" data-pal="${pal}" data-off="${off}" data-gid="${id}"${face?` data-sym="${sym}"`:''} viewBox="0 0 100 100" aria-hidden="true"><defs><radialGradient id="${id}g" cx="38%" cy="28%" r="78%"><stop offset="0" stop-color="${c.h}" stop-opacity=".95"/><stop offset=".36" stop-color="${c.b}"/><stop offset="1" stop-color="${c.a}"/></radialGradient></defs><g class="cd-faces">${cdFrame(kind,id,performance.now(),pal,off,face,sym)}</g></svg>`};window.HackeniaPolyDie=cornerDie;
{let last=0;const reduce=matchMedia('(prefers-reduced-motion:reduce)');const tick=now=>{requestAnimationFrame(tick);if(reduce.matches||document.hidden||now-last<33)return;last=now;document.querySelectorAll('svg.cd-svg[data-die]').forEach(sv=>{if(!sv.isConnected||!sv.getClientRects().length)return;const g=sv.querySelector('.cd-faces');if(g)g.innerHTML=cdFrame(sv.dataset.die,sv.dataset.gid,now,sv.dataset.pal||sv.dataset.die,+sv.dataset.off||0,!!sv.dataset.sym,sv.dataset.sym||'')})};requestAnimationFrame(tick)}
{const learn=document.createElement('button');learn.id='home-learn';learn.type='button';learn.setAttribute('aria-label','Apprendre à jouer : ouvrir les leçons du tutoriel');learn.innerHTML='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 6.5C10.3 5.2 8 4.8 4.5 5v12c3.5-.2 5.8.2 7.5 1.5 1.7-1.3 4-1.7 7.5-1.5V5c-3.5-.2-5.8.2-7.5 1.5ZM12 6.5v12"/></svg><span>Apprendre à jouer</span>';learn.addEventListener('click',()=>showLearning());learn.classList.add('corner-die','cd-v1');learn.innerHTML=cornerDie('d8')+'<span class="cd-label">Apprendre à jouer</span>';const about=document.createElement('button');about.id='home-about';about.type='button';about.className='corner-die cd-v2';about.setAttribute('aria-label','À propos d’Hackénia');about.innerHTML=cornerDie('d10')+'<span class="cd-label">À propos</span>';about.addEventListener('click',()=>{document.getElementById('about-dialog')?.remove();const d=document.createElement('dialog');d.id='about-dialog';d.setAttribute('aria-labelledby','about-title');d.innerHTML='<header><span class="about-die">'+cornerDie('d10')+'</span><h2 id="about-title">À propos</h2><button type="button" data-about="close" aria-label="Fermer">✕</button></header><div class="about-body"><fieldset><legend>Hackénia, c’est quoi ?</legend><p>Hackénia est un jeu de dés à collectionner de mon invention. Chaque dé cache un personnage ou une créature : posez-le sur le plateau, lancez-le pour le faire apparaître, puis frayez-vous un chemin jusqu’au camp adverse.</p><p>Collectionnez, composez vos decks, et affrontez les adversaires du jeu… ou vos ami(e)s en ligne.</p></fieldset><fieldset><legend>D’où vient l’histoire ?</legend><p>Tout a commencé autour d’une vraie table, avec des dés, des fiches de personnages et beaucoup de fous rires. Avant d’être un jeu, Hackénia est une campagne de jeu de rôle que nous jouons entre ami(e)s, session après session.</p><p>Les personnages et le monde d’Hackénia sont de mon invention, nourris par mon amour des grands classiques du jeu de rôle et de la fantasy.</p><p>Le mode Histoire raconte cette aventure : chaque chapitre reprend nos séances, avec leurs coups de génie, leurs plans foireux et leurs moments inoubliables. Les héros que vous suivez sont nés à cette table… leurs bêtises aussi.</p></fieldset><fieldset><legend>Un projet fait maison</legend><p>J’ai imaginé et construit Hackénia moi-même, et il grandit au fil de nos sessions et de vos retours. Une idée, un souci, une envie ? N’hésitez pas, elles sont toujours les bienvenues.</p><p>Hackénia est toujours en cours de développement : il évolue régulièrement, et les changements importants sont toujours annoncés dans le dé « Annonces » du menu principal.</p></fieldset><fieldset><legend>Contact</legend><p>Une question, un souci, une idée ? Écrivez-moi : <a href="mailto:contact.hackenia.tdg@gmail.com">contact.hackenia.tdg@gmail.com</a></p><p><a href="https://bulboel.github.io/Trading-dice-game/confidentialite.html" target="_blank" rel="noopener">Politique de confidentialité</a></p></fieldset><fieldset><legend>Merci</legend><p>Merci à mes ami(e)s de la table, sans qui rien de tout ça n’existerait, et merci à vous d’avoir lancé les dés. Bonne aventure sur Hacko !</p></fieldset><p class="opt-about-sign">Hackénia · Trading Dice Game · '+(document.getElementById('portal-build')?.textContent||'')+' · Créé par Bulboel</p></div>';d.addEventListener('click',e=>{if(e.target.closest('[data-about="close"]')||e.target===d)d.close()});d.addEventListener('close',()=>d.remove());document.body.append(d);window.HackeniaI18n?.apply?.(d);d.showModal()});const corner=document.createElement('div');corner.id='home-corner';corner.append(learn,about);document.body.append(corner)}const dialog=document.createElement('dialog');dialog.id='portal-detail';dialog.setAttribute('aria-label','Fiche du dé');document.body.append(dialog);const notice=document.createElement('div');notice.id='portal-toast';notice.className='portal-toast';notice.hidden=true;notice.setAttribute('role','status');document.body.append(notice);
const tabs=[['play','Jouer','#ff343e',1],['quick','Partie rapide','#ff6b26',2],['pvp','PVP en ligne','#ff9f24',6],['shop','Boutique','#ffe347',3],['story','Histoire','#b5f234',4],['collection','Collection','#25dc78',5],['decks','Mes decks','#23dbd0',6],['challenges','Défis','#339bff',5],['options','Options','#6054ff',2],['pantheon','Le Panthéon','#b542ff',4]];
const homeTips=["Pour gagner, tracez votre chemin grâce à vos dés pour rejoindre le camp ennemi","Vous pouvez aussi gagner en battant en duel 4 créatures adverses","Si vous ratez un jet de dés, un dé bonus vous est offert pour le suivant. Vous pouvez en cumuler jusqu’à trois et les lancer ensemble !","Un deck compte 10 dés. Chaque exemplaire ne peut y figurer qu’une fois ; vous pouvez toutefois le réutiliser dans vos autres decks.","Une victoire en mode Partie rapide avec les règles classiques vous offre 30 Bubulles !","Une défaite en Partie rapide ou dans le mode Jouer vous rapporte 5 Bubulles.","Votre créature apparaît sur la case marquée d’un liseré doré sur le schéma de son dé.","Vous pouvez taper sur l’astuce actuelle pour passer à l’astuce suivante !","Cliquez ou appuyez sur une créature en jeu pour voir sa puissance d’attaque et son élément. Cela peut être utile…","Un dé de niveau égal ou supérieur posé sur une créature adverse l’écrase !","Chaque jour, le dé Quotidien vous offre 30 Bubulles, et même 100 le 7e jour !","Un deck peut contenir au plus 1 dé divin, 2 légendaires, 2 dés Énergie et 4 rares.","Les dés élémentaires se posent sans lancer : parfaits pour prolonger un chemin vers le camp adverse.","Les dés de l’élément du terrain gagnent +1 en attaque : choisissez votre terrain avec soin ! (Automne : Terre et Vent ; Noël : Foudre, Glace et Feu.)","Terminez le chapitre 3 de l’Histoire pour gagner la Bague de l’Apprenti(e) : un dé bonus au début de chaque duel contre un adversaire du jeu. D’autres objets à porter se gagnent avec les défis (Options › Objet porté).","Notez votre code de récupération (Options › Sauvegarde) pour retrouver votre progression sur un autre téléphone.","Le dé Annonces vous présente les dernières nouveautés du jeu.","Touchez votre niveau, en haut à droite, pour voir vos quêtes du jour et de la semaine.","Chaque niveau rapporte des Bubulles, et les niveaux 5 et 10 débloquent de nouveaux effets de dé bonus.","Les créatures multi-élément comptent pour toutes les quêtes d’invocation, quel que soit l’élément demandé.","Trop d’exemplaires d’un même dé ? Recyclez vos doublons en Bubulles depuis la Collection.","Synergies : certains personnages liés gagnent +1 d’attaque quand ils sont ensemble sur le plateau. Regardez la fiche de vos créatures !","Au lac rose, guettez le nénuphar sacré : la créature posée dessus gagne +1 de force jusqu’au tour suivant.","Sur l’Île céleste, la foudre frappe deux cases au hasard à chaque tour : ne misez pas tout sur une seule créature !","Aux vents de Hacko, une petite tornade peut emporter une créature et sa dalle ailleurs : ne misez pas tout sur une seule route !","Pas de réseau ? Le jeu se lance hors ligne. Pour tout garder sur votre appareil : Options › Sauvegarde › Télécharger tout le jeu.","La force d’une créature est celle de la case où elle s’arrête : avant d’attaquer, finissez votre trajet sur votre meilleure dalle.",
"Quand une créature entre dans le camp adverse, tout son chemin disparaît avec elle, et les créatures posées dessus aussi. Gardez une route de secours !",
"Bonus de voisin : une dalle gagne +1 si une dalle voisine porte l’élément qu’elle domine. Placez vos dés en conséquence.",
"Si tous vos dés montrent la même face, l’invocation réussit toujours, même sous le résultat demandé ! Le résultat demandé est indiqué sur chaque dé : 2+ commun, 3+ peu commun, 4+ rare, 4+ légendaire (2 dés) et 5+ divin (2 dés).",
"Égalité en combat ? Les deux créatures disparaissent et chaque camp compte un ennemi vaincu.",
"Sur la Route vers Forfalla, vos créatures glissent jusqu’au bout des dalles libres : un ennemi sur la route les arrête… et déclenche le combat.",
"Aux Terres embrasées, les évents de magma sont infranchissables : ils coupent les routes et bloquent les poses.",
"Pressé ? Le bouton ⏩ en haut de la partie (ou Options › Partie) active les tours rapides : l’adversaire, les lancers et les combats vont plus vite.",
"Sur ordinateur, appuyez sur Espace pour lancer le dé que vous venez de placer, ou pour confirmer un déplacement.",
"Le bouton Historique, en haut de la partie, retrace chaque lancer et chaque combat avec les forces de chaque camp.",
"Le bouton Boubourse, pendant la partie, montre les dés qui vous restent à piocher : utile pour préparer vos prochains tours.",
"Dans Collection, touchez un dé pour ouvrir sa fiche : forme dépliée, synergies et personnage en 3D.",
"Options › Dés & boubourse : choisissez le style de vos dés de jet et la couleur, la texture et le cordon de votre boubourse.",
"Mort subite ! Trois 6 sur un même lancer de trois ou quatre dés, et la partie est gagnée sur-le-champ. Quatre 6 : +10 Bubulles en prime !",
"Une créature sélectionnée par erreur ? Touchez-la à nouveau, ou touchez une autre case, pour la désélectionner.",
"PVP en ligne : ouvrez une table pour que n’importe quel joueur vous rejoigne, sans code à échanger. Choisissez Duel (1 contre 1) ou 2 contre 2 en haut de la page.",
"Débutant ? Choisissez la ville de Dassom (terrain neutre) et touchez « ✨ Deck optimal pour ce terrain » dans Jouer : le jeu compose votre deck pour vous.",
"Mode Jouer : choisissez la forme du plateau (Étroit, Piliers, Sablier, Deux gués) pour varier vos parties.",
"La ville de Dassom, la grotte souterraine et le Colisée sont des terrains neutres : aucun élément n’y est favorisé.",
 "Au Colisée, chaque moitié des gradins soutient un camp : réussis un beau lancer et la foule t’acclame… rate-le et elle te hue !",
"Une créature qui vient d’apparaître ne peut se déplacer qu’à partir de votre tour suivant.",
"Dans Mes decks, préparez plusieurs decks (un par terrain, par exemple) et choisissez-en un avant chaque partie.","Dès le niveau 5, proposez votre propre dé depuis la Collection : s’il est validé, il rejoint le jeu avec votre nom !","Défis › Les Contes de la Taverne : écrivez une scène de jeu de rôle, elle sera peut-être jouée et racontée dans le podcast !",
"Débutant ? « Apprendre à jouer » propose 4 petites leçons d’une minute : placer un dé, traverser le terrain, les combats, les affinités. Vous pouvez rejouer chaque leçon quand vous voulez.",
"Double clic (ordinateur) ou double toucher (smartphone) sur une créature du terrain : sa fiche s’ouvre tout de suite.",
"2 contre 2 : deux équipes de deux jouent à tour de rôle. Victoire : 3 passages ou 6 combats pour l’équipe. Hors ligne comme en ligne, des équipiers virtuels peuvent compléter l’équipe.",
"Un dé multi-élément (Lumérion, Floréa, Jordan, la Grande araignée blanche…) reçoit toujours le bonus de terrain, mais jamais le bonus de voisin.",
"Jordan, le destrier de Bolduc, gagne +1 PA par Bolduc allié sur le plateau (2 au plus). Pensez à le placer dans le même deck !",
"Dés à effet : une dalle de moins, mais un pouvoir (+1 PA selon la situation). Lisez la fiche du dé pour connaître son effet.",
"Dés de carte : posés sans lancer, ils laissent un mur de glace (bloque 3 tours) ou un piège invisible pour l’adversaire à la place d’une créature.",
"Dés de classe : le soigneur reprend une dalle perdue, l’éclaireur révèle la main adverse pendant 2 tours.",
"Objets portés (Options › Objet porté) : un seul à la fois. Bague de l’Apprenti(e), Grelot des neiges, Feuille d’or, Lanterne du mineur, Écharpe de Kayla ou Sac sans fond, gagnés avec les défis.",
"Boutique : 0,4 % de chances d’obtenir un dé divin par dé tiré. Une garantie vous offre un divin toutes les 80 boubourses sans divin, et un légendaire toutes les 50 boubourses sans légendaire.",
"La roue des éléments est à droite du plateau : déplacez la vue pour la voir. L’eau domine le feu, le feu la glace, la glace la terre, la terre le vent, le vent la foudre, la foudre l’eau.",
"Les dés crépitants sont extrêmement rares : arriverez-vous à compléter leur collection ?",
"Un dé Max, Orcus, Eberien… existe en plusieurs versions (légendaire, argent, or) : regardez la Collection pour toutes les retrouver, groupées par personnage."];
let activeMatchMode=null;
let homeTipIndex=Math.floor(Math.random()*homeTips.length),homeTipTimer=null,homeTipChanging=false;
function scheduleHomeTip(){clearTimeout(homeTipTimer);homeTipTimer=null;if(view==='home')homeTipTimer=setTimeout(nextHomeTip,20000)}
function nextHomeTip(){if(view!=='home'||homeTipChanging)return;const text=$('home-tip-text');if(!text)return;homeTipChanging=true;clearTimeout(homeTipTimer);let next;do{next=Math.floor(Math.random()*homeTips.length)}while(next===homeTipIndex);text.classList.add('is-changing');setTimeout(()=>{homeTipIndex=next;text.textContent=homeTips[next];text.classList.remove('is-changing');homeTipChanging=false;scheduleHomeTip()},280)}

const menuIcons={pantheon:'<path d="M2 9 12 3l10 6H2Zm2 11h16M3 23h18M6 10v9m6-9v9m6-9v9"/>',pvp:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3q5 5 0 18M12 3q-5 5 0 18"/>',play:'<path d="m9 5 11 7-11 7Z"/>',quick:'<path d="m13 2-9 12h7l-1 8 10-12h-7Z"/>',shop:'<path d="M7 3q5 3 10 0l-2 5q7 7 6 11-1 4-9 4s-11-3-9-7q2-5 6-8Z"/><path d="M7 8h10M15 8q6-2 5 2t-5-2"/>',story:'<path d="M12 5q-5-3-10-1v16q5-2 10 1 5-3 10-1V4q-5-2-10 1Zm0 0v16"/>',collection:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',decks:'<rect x="7" y="3" width="13" height="17" rx="2"/><path d="M4 6v14q0 3 3 3h10M10 7h7M10 11h7M10 15h5"/>',challenges:'<path d="M8 3h8v4h4v3q0 5-6 6l-1 3h4v2H7v-2h4l-1-3q-6-1-6-6V7h4Z"/><path d="M8 7h8M4 8H2m20 0h-2"/>',options:'<path d="m10 2-1 3-3 1-3-1-2 4 3 2v3l-3 2 2 4 3-1 3 1 1 3h4l1-3 3-1 3 1 2-4-3-2v-3l3-2-2-4-3 1-3-1-1-3Z"/><circle cx="12" cy="12.5" r="3.5"/>'};
function menuPips(n){const map={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};return '<span class="menu-pips">'+Array.from({length:9},(_,i)=>'<i'+(map[n].includes(i)?' class="pip"':'')+'></i>').join('')+'</span>'}
$('portal-nav').setAttribute('aria-label','Menu principal. Faites glisser pour tourner les dés.');
$('portal-nav').innerHTML='<button id="home-tip" class="home-tip" type="button" aria-label="Astuce de jeu. Touchez pour afficher la suivante." title="Afficher l’astuce suivante"><strong class="home-tip-heading">Astuces</strong><span id="home-tip-text" class="home-tip-text" aria-live="polite">'+homeTips[homeTipIndex]+'</span><span class="home-tip-spark" aria-hidden="true">✧</span></button><div id="home-dice-ring" class="home-dice-ring">'+tabs.map(([v,n,c,pips],i)=>`<button class="portal-tab" type="button" data-view="${v}" style="--accent:${c};--ring-x:${(50+50*Math.cos((i/tabs.length)*2*Math.PI-Math.PI/2)).toFixed(3)}%;--ring-y:${(50+50*Math.sin((i/tabs.length)*2*Math.PI-Math.PI/2)).toFixed(3)}%" aria-label="${n}" title="${n}"><span class="menu-die-shadow" aria-hidden="true"></span><span class="menu-die-visual" aria-hidden="true"><span class="menu-cube"><span class="md-core md-core-x"></span><span class="md-core md-core-y"></span><span class="md-core md-core-z"></span><span class="md-face md-front"><span class="menu-emblem"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round">${menuIcons[v]}</svg></span><i class="md-stud a"></i><i class="md-stud b"></i><i class="md-stud c"></i><i class="md-stud d"></i></span><span class="md-face md-top">${menuPips(pips)}</span><span class="md-face md-right">${menuPips(7-pips)}</span><span class="md-face md-back"><span class="menu-emblem"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round">${menuIcons[v]}</svg></span></span><span class="md-face md-left">${menuPips(pips)}</span><span class="md-face md-bottom">${menuPips(7-pips)}</span></span></span><strong>${n}</strong><span class="menu-selected-mark" aria-hidden="true"></span></button>`).join('')+'</div>';
$('portal-nav').onclick=e=>{const b=e.target.closest('[data-view]');if(!b)return;if(b.closest('#home-dice-ring')&&view==='home')diveInto(b,()=>navigate(b.dataset.view,true));else navigate(b.dataset.view,true)};$('home-tip').onclick=nextHomeTip;
const ring=$('home-dice-ring');let ringAngle=0,ringDrag=null,suppressRingClickUntil=0,ringInertiaFrame=0;
function setRingAngle(angle){ringAngle=((angle%360)+360)%360;ring.style.setProperty('--dice-ring-angle',ringAngle+'deg');ring.style.setProperty('--dice-ring-counter-angle',(-ringAngle)+'deg')}
function startRingInertia(velocity){cancelAnimationFrame(ringInertiaFrame);if(Math.abs(velocity)<6)return;let previous=performance.now();function coast(now){const dt=Math.min((now-previous)/1000,.05);previous=now;setRingAngle(ringAngle+velocity*dt);velocity*=Math.exp(-2*dt);if(Math.abs(velocity)>3)ringInertiaFrame=requestAnimationFrame(coast);else ringInertiaFrame=0}ringInertiaFrame=requestAnimationFrame(coast)}
setRingAngle(0);
ring.addEventListener('pointerdown',e=>{if(e.button!==0&&e.pointerType!=='touch')return;cancelAnimationFrame(ringInertiaFrame);ringInertiaFrame=0;const rect=ring.getBoundingClientRect(),cx=rect.left+rect.width/2,cy=rect.top+rect.height/2,px=e.clientX-cx,py=e.clientY-cy;ringDrag={id:e.pointerId,startX:e.clientX,startY:e.clientY,startAt:performance.now(),lastX:e.clientX,lastY:e.clientY,lastAt:performance.now(),lastAngle:Math.atan2(py,px),lastRadius:Math.hypot(px,py),total:0,velocity:0,peakVelocity:0,dragged:false}});
ring.addEventListener('pointermove',e=>{if(!ringDrag||e.pointerId!==ringDrag.id)return;const rect=ring.getBoundingClientRect(),cx=rect.left+rect.width/2,cy=rect.top+rect.height/2,px=e.clientX-cx,py=e.clientY-cy,radius=Math.hypot(px,py),angle=Math.atan2(py,px),dx=e.clientX-ringDrag.lastX,dy=e.clientY-ringDrag.lastY;if(!ringDrag.dragged&&Math.hypot(e.clientX-ringDrag.startX,e.clientY-ringDrag.startY)>7){ringDrag.dragged=true;ring.classList.add('is-dragging');try{ring.setPointerCapture(e.pointerId)}catch{}}if(ringDrag.dragged){const now=performance.now(),dt=Math.max(.008,(now-ringDrag.lastAt)/1000);let step;if(radius>28&&ringDrag.lastRadius>28){let delta=angle-ringDrag.lastAngle;if(delta>Math.PI)delta-=Math.PI*2;if(delta<-Math.PI)delta+=Math.PI*2;step=delta*180/Math.PI}else step=(dx/rect.width-dy/rect.height)*180;const instant=Math.max(-1100,Math.min(1100,step/dt));ringDrag.velocity=ringDrag.velocity*.38+instant*.62;if(Math.abs(instant)>Math.abs(ringDrag.peakVelocity))ringDrag.peakVelocity=instant;ringDrag.total+=step;setRingAngle(ringAngle+step);ringDrag.lastX=e.clientX;ringDrag.lastY=e.clientY;ringDrag.lastAngle=angle;ringDrag.lastRadius=radius;ringDrag.lastAt=now;e.preventDefault()}});
function endRingDrag(e){if(!ringDrag||e.pointerId!==ringDrag.id)return;const dragged=ringDrag.dragged,duration=Math.max(.08,(performance.now()-ringDrag.startAt)/1000),total=ringDrag.total,average=total/duration;let velocity=ringDrag.velocity;if(Math.abs(ringDrag.peakVelocity)*.7>Math.abs(velocity))velocity=ringDrag.peakVelocity*.7;if(Math.abs(average)*.8>Math.abs(velocity))velocity=average*.8;const distanceImpulse=Math.abs(total)>18?Math.sign(total)*Math.min(420,Math.abs(total)*2.2):0;if(Math.abs(distanceImpulse)>Math.abs(velocity))velocity=distanceImpulse;ringDrag=null;ring.classList.remove('is-dragging');if(dragged){suppressRingClickUntil=performance.now()+400;startRingInertia(Math.max(-900,Math.min(900,velocity)))}}
ring.addEventListener('pointerup',endRingDrag);ring.addEventListener('pointercancel',endRingDrag);
ring.addEventListener('click',e=>{if(performance.now()<suppressRingClickUntil){e.preventDefault();e.stopImmediatePropagation()}},true);
$('portal-back').onclick=()=>navigate('home',true);{/* v387 — toucher le nom ou le logo ramène au menu principal ; le titre se réduit pour ne jamais toucher le bouton maison */const brand=shell.querySelector('.portal-brand');brand.setAttribute('role','link');brand.tabIndex=0;brand.title='Menu principal';const goHome=()=>{if(view!=='home')navigate('home',true)};brand.addEventListener('click',goHome);brand.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();goHome()}});
 const fitBrand=()=>{const h=shell.querySelector('.portal-wordmark h1'),back=$('portal-back');if(!h)return;h.style.fontSize='';if(view==='home'||!back||back.hidden)return;const hr=h.getBoundingClientRect(),br=back.getBoundingClientRect();if(!hr.width||!br.width)return;const avail=br.left-hr.left-14;if(avail<=40)return;for(let i=0;i<6&&h.scrollWidth>avail;i++){const fs=parseFloat(getComputedStyle(h).fontSize);if(fs<=12)break;h.style.setProperty('font-size',Math.max(12,fs*Math.max(.8,avail/h.scrollWidth)-.3).toFixed(1)+'px','important')}};
 window.HackeniaFitBrand=fitBrand;addEventListener('resize',()=>requestAnimationFrame(fitBrand));document.fonts?.ready?.then(()=>fitBrand())}$('portal-level').onclick=()=>navigate('challenges',true);
if(typeof ResizeObserver!=='undefined')new ResizeObserver(entries=>shell.style.setProperty('--portal-header-height',Math.ceil(entries[0].target.getBoundingClientRect().height)+'px')).observe(shell.querySelector('.portal-head'));
function bubulles(n){return n.toLocaleString('fr-FR')+' '+(n===1?'bubulle':'Bubulles')}
function rewardMatch(won,event){if(!storageOK||recovery)return;const mode=event.gameMode||activeMatchMode,C=window.HackeniaChallenges;let next=window.HackeniaMatchRewards.plan(profile,won,mode,event.difficulty)||profile;const before=C.unlocked(profile).length;next=C.advance(next,{won,terrain:event.terrain||game.snapshot().terrain,mode,difficulty:event.difficulty});const gain=progressMatch(next,won?'win':'loss',mode,event.difficulty);if(gain)next=gain.profile;if(won&&event.superSudden&&['quick','play','online','story'].includes(mode)){next=structuredClone(next);next.gold=(next.gold||0)+10;setTimeout(()=>questToast('☠ Super mort subite ! +10 Bubulles'),1200)}/* v247 */if(['quick','play','online'].includes(mode)){next=structuredClone(next);const stats=next.matchStats||{wins:0,losses:0,draws:0},key=won?'wins':'losses';stats[key]=(Number.isSafeInteger(stats[key])?stats[key]:0)+1;stats.lastResult=won?'win':'loss';next.matchStats=stats;}if(next!==profile&&commit(next)){const gained=C.unlocked(next).length-before;toast((['quick','play'].includes(mode)?won?'Victoire ! +'+window.HackeniaMatchRewards.amount(true,mode,event.difficulty)+' Bubulles 🎉':'Défaite · +5 Bubulles pour cette partie.':won?'Victoire !':'Partie terminée.')+(gain?.xp?' · +'+gain.xp+' XP':'')+(gained?' ✦ '+gained+' défi'+(gained>1?'s accomplis':' accompli')+' !':''));if(gain)announceProgress(gain)}}
