function updateStartChoices(){if(!startMenu)return;const load=startMenu.querySelector('[data-start="load"]');if(load){load.disabled=!hasSavedProfile;load.querySelector('small').textContent=hasSavedProfile?'Reprendre votre progression':'Aucune partie sauvegardée sur cet appareil'}}
function showStartMenu(){game.pause();if(!startMenu){startMenu=document.createElement('main');startMenu.id='start-menu';startMenu.setAttribute('aria-labelledby','start-title');document.body.prepend(startMenu);startMenu.addEventListener('click',event=>{const button=event.target.closest('[data-start]');if(!button||button.disabled)return;const action=button.dataset.start;if(action==='new')requestNewGame();else if(action==='load')loadSavedGame();else if(action==='learn')showLearning();else if(action==='back')showStartMenu()})}
 startMenu.innerHTML='<div class="start-content"><img class="start-logo" src="assets/hackenia-logo-v112.svg" width="118" height="118" alt="Dé de Hackenia dans sa bulle"><h1 id="start-title">Dice of Hackenia</h1><p class="start-subtitle">Trading Dice Game</p><div class="start-choices"><button type="button" class="start-choice" data-start="new">'+startGlyph('new')+'<span><strong>Nouvelle partie</strong><small>50 Bubulles pour commencer votre aventure</small></span></button><button type="button" class="start-choice" data-start="load">'+startGlyph('load')+'<span><strong>Charger partie</strong><small>Reprendre votre progression</small></span></button><button type="button" class="start-choice" data-start="learn">'+startGlyph('learn')+'<span><strong>Apprendre à jouer</strong><small>Découvrir les règles et vos premiers pas</small></span></button></div><p class="start-footnote">Votre aventure est sauvegardée sur cet appareil.</p><p class="lang-switch" role="group" aria-label="Langue / Language"><button type="button" data-lang="fr" aria-pressed="'+(window.HackeniaI18n?.lang==='fr')+'">Français</button><button type="button" data-lang="en" aria-pressed="'+(window.HackeniaI18n?.lang==='en')+'">English</button></p></div>';startMenu.hidden=false;document.body.classList.add('start-menu-open');updateStartChoices();window.scrollTo({top:0,left:0,behavior:'instant'});
}
