function beginNewGame(){if(starting)return;starting=true;const next=starter();if(!window.HackeniaProfileTools.start(localStorage,next)){starting=false;toast('La nouvelle partie n’a pas pu être enregistrée. Votre progression est conservée.');return}game.resetSession?.();profile=next;hasSavedProfile=true;storageOK=true;recovery=false;draft={id:null,name:'Mon premier deck',dice:[]};latest=[];latestFirstSeen=[];activeMatchMode=null;starting=false;showLearning()}
