function skillsView(){const S=window.HackeniaSkills;$('portal-content').innerHTML=S?S.treeHTML(profile,window.HackeniaHero?.avatarSrc?.()||profile.hero?.avatar||''):'<p class="portal-muted">Indisponible.</p>'}
// v219 — Niveau de joueur et quêtes (en tête de l'écran Défis).
function progressPanel(){const P=window.HackeniaProgress;if(!P)return '';if(storageOK){const fresh=P.ensure(profile);if(fresh!==profile)commit(fresh)}const v=P.view(profile),pct=v.max?100:Math.round(v.into/v.need*100),h=Math.floor(v.resetIn/36e5),m=Math.floor(v.resetIn%36e5/6e4);
 const quest=(q,weekly)=>`<li class="quest${q.done?' done':''}${weekly?' weekly':''}"><span class="quest-check" aria-hidden="true">${q.done?'✔':weekly?'★':'◇'}</span><span class="quest-copy"><strong>${esc(q.text)}</strong><span class="quest-bar"><i style="width:${Math.round(q.progress/q.target*100)}%"></i></span></span><span class="quest-side"><b>${q.progress} / ${q.target}</b><small>+${q.reward.xp} XP · +${q.reward.gold} 🫧</small></span></li>`;
 const discord=window.HACKENIA_COMMUNITY?.discord;return `<div class="community-links"><button type="button" class="tales-btn" data-action="tales">📜 Les Contes de la Taverne <small>concours de scènes de jeu de rôle</small></button>${discord?`<a class="discord-btn" href="${esc(discord)}" target="_blank" rel="noopener">💬 Rejoindre la communauté</a>`:''}</div><section class="progress-panel" aria-label="Niveau et quêtes"><div class="pp-level"><div class="pp-badge" style="--pct:${pct}"><b>${v.level}</b><small>Niveau</small></div><div class="pp-copy"><h2>Niveau ${v.level}${profile.creator?.badge?' <span class="creator-badge" title="Un de vos dés a été accepté dans la collection">✦ Créateur</span>':''}${profile.scenarist?.badge?' <span class="creator-badge scenarist" title="Votre scène a gagné un concours des Contes de la Taverne">🎭 Scénariste</span>':''}</h2><div class="pp-bar" role="progressbar" aria-valuemin="0" aria-valuemax="${v.need}" aria-valuenow="${v.into}"><i style="width:${pct}%"></i></div><p>${v.max?'Niveau maximum atteint !':`${v.into} / ${v.need} XP · prochain niveau : <b>+${v.nextReward.gold} Bubulles</b>`}${v.nextUnlock?` · <span class="pp-unlock">Niveau ${v.nextUnlock.level} : ${esc(v.nextUnlock.label)}</span>`:''}</p><p class="pp-help">XP : victoire 40 (jusqu’à 60 contre un adversaire difficile), défaite 15, Histoire 50, PVP 80. Chaque niveau rapporte des Bubulles, et tous les 5 niveaux un palier de +100.</p></div></div>${skillEntry()}
 <div class="pp-quests"><h3>Quêtes du jour <small>nouvelles quêtes dans ${h} h ${String(m).padStart(2,'0')}</small></h3><ul>${v.daily.map(q=>quest(q,false)).join('')}</ul><h3>Quête de la semaine <small>renouvelée chaque lundi</small></h3><ul>${quest(v.weekly,true)}</ul></div></section>`}
function challenges(){const C=window.HackeniaChallenges;const unlocked=C.unlocked(profile);$('portal-content').innerHTML=progressPanel()+'<div class="portal-title"><div><h2>Défis d’Hackénia</h2><p>'+unlocked.length+' / '+C.definitions.length+' défis accomplis</p></div><button data-action="options">Personnaliser mes récompenses</button></div><p class="portal-muted">Les défis progressent en Jouer, Partie rapide, PVP et Histoire. Les récompenses se débloquent automatiquement dans les Options. Progression comptée à partir de cette mise à jour.</p><div class="challenge-list">'+C.definitions.filter(d=>!d.hidden||C.progress(profile,d)>=d.target).map(d=>{const n=C.progress(profile,d),done=n>=d.target;return '<details class="challenge-card '+(done?'complete':'')+'"><summary><span class="challenge-seal" aria-hidden="true">'+(done?'✦':'◇')+'</span><strong>'+esc(d.title)+(d.event?' <span class="challenge-event">❄ Événement</span>':'')+'</strong><span class="challenge-count">'+n+' / '+d.target+'</span></summary><div class="challenge-body"><p>'+esc(d.goal)+'</p><progress max="'+d.target+'" value="'+n+'" aria-label="Progression du défi '+esc(d.title)+'"></progress><p class="challenge-reward"><span>Récompense</span> '+esc(d.reward)+'</p>'+(done?'<b class="challenge-done">Débloqué dans les Options</b>':'')+'</div></details>'}).join('')+'</div>'}

function render(){window.HackeniaPouch?.dispose($('pouch-theatre'));if(view==='home')home();else if(view==='options')options();else if(view==='play')play();else if(view==='collection')collection();else if(view==='decks')decks();else if(view==='challenges')challenges();else if(view==='skills')skillsView();else if(view==='pantheon')pantheon();else if(view==='propose')window.HackeniaSubmit?window.HackeniaSubmit.render($('portal-content')):$('portal-content').innerHTML='<p>Chargement…</p>';else if(view==='admin')window.HackeniaSubmit?.renderAdmin($('portal-content'));else if(view==='tales')window.HackeniaTales?.render($('portal-content'));else if(view==='shop')shop();else if(view==='packs')packs();else if(view==='pvp'&&!navigator.onLine)$('portal-content').innerHTML='<div class="portal-title"><div><h2>PVP en ligne</h2></div></div><p>Vous êtes hors ligne. Le PVP nécessite une connexion Internet : reconnectez-vous puis revenez ici. En attendant, toutes les autres parties (Jouer, Partie rapide, Histoire) fonctionnent hors ligne.</p>';else if(view==='pvp')window.HackeniaPVP?window.HackeniaPVP.mount($('portal-content'),pvpBridge):$('portal-content').innerHTML='<p>Le mode en ligne est indisponible.</p>';else if(view==='story'){if(window.HackeniaStory)window.HackeniaStory.render($('portal-content'));else $('portal-content').innerHTML='<div class="history-coming"><h2>Histoire</h2><p>Chargement…</p></div>'}else quick()}
const pvpBridge={aiDeck:l=>window.hackeniaGame?.aiDeck?.(l),getProfile:()=>profile,commit:p=>commit(p),toast:m=>toast(m),legal:d=>legal(d),defs,rarity:d=>rarity(d),
 enterMatch(f){activeMatchMode='online';window.HackeniaView?.clearPreview?.();document.body.classList.remove('portal-open');location.hash='partie';f();window.HackeniaSettings?.syncMusic?.();window.dispatchEvent(new Event('resize'));setTimeout(()=>window.HackeniaPVP?.updateHud(),50)},
 toMenu:()=>navigate('home',true)};
function launch(dice,terrain=null,kind=Array.isArray(dice)?'play':'quick',level='difficile',layout='classique',team2=false){activeMatchMode=kind;if(profile.onb){delete profile.onb;try{localStorage.setItem(KEY,JSON.stringify(profile))}catch{}}if(!profile.firstMatchStarted){profile.firstMatchStarted=true;try{localStorage.setItem(KEY,JSON.stringify(profile))}catch{}}window.HackeniaView?.clearPreview?.();document.body.classList.remove('portal-open');location.hash='partie';game.start(dice,terrain,kind,level,null,layout,team2);window.HackeniaSettings?.syncMusic?.();window.dispatchEvent(new Event('resize'))}
