 const terrainOptions=terrainList.filter(([id])=>window.HackeniaEvents?.terrainOpen?.(id)??id!=='noel').map(([id,em,name])=>'<option value="'+id+'">'+name+'</option>').join('');
 /* v252 — sélecteur visuel : chaque terrain avec la miniature 3D de son dé d'élément (anneau des six éléments pour les terrains neutres) */
