 $('portal-content').innerHTML='<div class="portal-title"><div><h2>Jouer</h2></div><span class="portal-muted">Duel contre un adversaire</span></div><p>Choisissez votre deck et le terrain ; son aperçu montre le plateau réel avant le lancement.</p><div class="deck-layout play-layout"><div class="play-controls play-pick"><label for="play-deck">Votre deck</label><select id="play-deck" style="width:100%;padding:12px;margin:8px 0 16px">'+(available.length?'':'<option value="">Aucun deck jouable</option>')+deckOptions+'</select><label for="play-terrain">Terrain</label><select id="play-terrain" class="terrain-native" tabindex="-1" aria-hidden="true">'+terrainOptions+'</select>'+terrainPicker+'</div><section class="terrain-preview" id="play-terrain-preview" data-terrain="terre" aria-live="polite"><div class="terrain-preview-art" id="play-terrain-art" aria-label="Aperçu réel du plateau de jeu"></div><div class="terrain-preview-copy"><span class="terrain-preview-kicker">Aperçu du terrain</span><strong id="terrain-preview-title">Le Bois tendre</strong><span id="terrain-preview-text">Une clairière boisée traversée par une rivière.</span><small id="terrain-preview-effect">Les dés de terre gagnent +1 en attaque.</small></div></section><div class="play-controls play-rest"><label for="play-layout">Forme du plateau</label><select id="play-layout" style="width:100%;padding:12px;margin:8px 0 16px"><option value="classique">Classique · plateau libre</option><option value="etroit">Étroit · bords infranchissables</option><option value="piliers">Piliers · huit rochers à contourner</option><option value="sablier">Sablier · un goulet au centre</option><option value="riviere">Deux gués · deux murs à franchir</option></select><label class="team2-opt" for="play-team2"><input type="checkbox" id="play-team2"><span><b>👥 2 contre 2</b><small>Un allié joue avec vous contre deux adversaires. Victoire : 3 passages ou 6 combats.</small></span></label><label for="play-level">Difficulté de l’adversaire</label><select id="play-level" style="width:100%;padding:12px;margin:8px 0 6px">'+[['facile','Facile','20'],['moyen','Moyenne','30'],['difficile','Difficile','40'],['divin','Divine','50']].map(([v,n,g])=>'<option value="'+v+'"'+((profile.preferredLevel||'moyen')===v?' selected':'')+'>'+n+' · +'+g+' Bubulles</option>').join('')+'</select>'+(()=>{const over=profile.decks.filter(d=>limitProblem(d.dice));return over.length?'<p class="portal-muted play-level-note">'+over.map(d=>'« '+esc(d.name)+' » dépasse les limites ('+limitProblem(d.dice)+')').join(' · ')+' : modifiez-le dans « Mes decks ».</p>':''})()+'<div class="deck-actions"><button class="portal-primary" data-action="start-play" '+(preferred?'':'disabled')+'>Lancer le duel ↗</button><button data-action="play-optimal" title="Compose et sélectionne le meilleur deck pour le terrain choisi">✨ Deck optimal pour ce terrain</button><button data-action="decks-from-play">Composer un deck</button></div>'+(available.length?'':'<p class="portal-muted">Aucun deck sauvegardé valide. Créez et sauvegardez un deck de 10 dés dans « Mes decks ».</p>')+'</div></div>';
 const sel=$('play-deck'),start=$('portal-content').querySelector('[data-action="start-play"]'),terrain=$('play-terrain');
 {const opt=$('portal-content').querySelector('[data-action="play-optimal"]'),dk=$('play-deck');if(opt&&dk){opt.classList.add('play-optimal-btn');dk.insertAdjacentElement('afterend',opt);if(profile.onb==='play'){opt.classList.add('onb-target');opt.insertAdjacentHTML('afterend','<div class="onb-callout" role="note"><b>Clique ici</b> pour avoir un deck rapide et jouer tout de suite ! Si tu veux le faire toi-même, n’hésite pas à aller dans le menu « Mes decks ». Ensuite clique sur <b>Lancer le duel</b>. Bon jeu à toi !</div>')}}}
